const raw = env.get('REDIS_STREAM_GROUPS_JSON') || flow.get('redisStreamGroups');
const defaultTarget = String(env.get('REDIS_TARGET') || 'redis-primary').trim();
const configuredLimit = Number(env.get('REDIS_STREAM_METRICS_MAX_PAIRS') || 500);
const pairLimit = Number.isFinite(configuredLimit) && configuredLimit > 0 ? Math.floor(configuredLimit) : 500;
let configured = raw;

if (typeof configured === 'string') {
    try { configured = JSON.parse(configured); } catch (error) {
        node.error('REDIS_STREAM_GROUPS_JSON must be valid JSON: ' + error.message, msg);
        return null;
    }
}
if (!Array.isArray(configured)) {
    node.error('Set REDIS_STREAM_GROUPS_JSON (or flow.redisStreamGroups) to an array of {stream, group, deadLetterStream?}.', msg);
    return null;
}
const seen = new Set();
const jobs = [];
for (const item of configured) {
    if (!item || typeof item !== 'object') continue;
    const stream = String(item.stream || '').trim();
    const group = String(item.consumerGroup || item.group || '').trim();
    const redisTarget = String(item.redisTarget || defaultTarget).trim();
    const deadLetterStream = item.deadLetterStream ? String(item.deadLetterStream).trim() : '';
    if (!stream || !group || !redisTarget) continue;
    const key = redisTarget + '\u0000' + stream + '\u0000' + group;
    if (seen.has(key)) continue;
    seen.add(key);
    jobs.push({ stream, group, redisTarget, deadLetterStream });
}
if (jobs.length > pairLimit) {
    node.error('Inventory has ' + jobs.length + ' stream/group pairs, above REDIS_STREAM_METRICS_MAX_PAIRS=' + pairLimit + '.', msg);
    return null;
}
if (!jobs.length) return null;
msg.payload = jobs;
return msg;

const job = msg.payload;
if (!job || !job.stream || !job.group || !job.redisTarget) {
    node.error('Invalid stream/group collection job.', msg);
    return null;
}
msg.stream = job.stream;
msg.group = job.group;
msg.redisTarget = job.redisTarget;
msg.deadLetterStream = job.deadLetterStream || undefined;
msg.payload = null;
return msg;

const snapshot = msg.payload;
const optionalNumber = (value) => {
    if (value === null || value === undefined || value === '') return null;
    const number = Number(value);
    return Number.isFinite(number) && number >= 0 ? number : null;
};
const requiredNumber = (name, value) => {
    const number = optionalNumber(value);
    if (number === null) throw new Error('Snapshot field ' + name + ' must be a non-negative finite number.');
    return number;
};

try {
    if (!snapshot || typeof snapshot !== 'object') throw new Error('Redis stream metrics node returned no snapshot.');
    const stream = String(snapshot.stream || msg.stream || '').trim();
    const group = String(snapshot.group || msg.group || '').trim();
    const redisTarget = String(msg.redisTarget || '').trim();
    if (!stream || !group || !redisTarget) throw new Error('Snapshot is missing stream, group, or redisTarget.');

    const pending = requiredNumber('pending', snapshot.pending);
    const consumers = requiredNumber('consumers', snapshot.consumers);
    const lag = optionalNumber(snapshot.lag);
    const entriesRead = optionalNumber(snapshot.entriesRead);
    const sampledAtMs = Date.parse(snapshot.sampledAt);
    if (!Number.isFinite(sampledAtMs)) throw new Error('Snapshot field sampledAt must be an ISO timestamp.');

    const dlqConfigured = typeof snapshot.deadLetterStream === 'string' && snapshot.deadLetterStream.trim() ? 1 : 0;
    const dlqLength = optionalNumber(snapshot.deadLetterLength);
    const lastDeliveredMatch = /^(\d+)-\d+$/.exec(String(snapshot.lastDeliveredId || ''));
    const lastDeliveredMs = lastDeliveredMatch ? Number(lastDeliveredMatch[1]) : null;
    const lastDeliveredTimestamp = Number.isSafeInteger(lastDeliveredMs) && lastDeliveredMs > 0 ? lastDeliveredMs / 1000 : null;
    const labels = { redis_target: redisTarget, stream, consumer_group: group };
    const gauge = (value) => ({ payload: { op: 'set', val: value, labels } });

    return [
        gauge(pending),
        lag === null ? null : gauge(lag),
        gauge(lag === null ? 0 : 1),
        gauge(consumers),
        entriesRead === null ? null : gauge(entriesRead),
        gauge(entriesRead === null ? 0 : 1),
        gauge(dlqConfigured),
        dlqConfigured && dlqLength !== null ? gauge(dlqLength) : null,
        gauge(dlqConfigured && dlqLength !== null ? 1 : 0),
        gauge(sampledAtMs / 1000),
        lastDeliveredTimestamp === null ? null : gauge(lastDeliveredTimestamp),
        gauge(lastDeliveredTimestamp === null ? 0 : 1)
    ];
} catch (error) {
    node.error('Invalid Redis stream consumer-group snapshot: ' + error.message, msg);
    return null;
}

const redisTarget = String(msg.redisTarget || '').trim();
const stream = String(msg.stream || '').trim();
const group = String(msg.group || '').trim();
if (!redisTarget || !stream || !group) return null;
msg.payload = {
    op: 'inc',
    val: 1,
    labels: { redis_target: redisTarget, stream, consumer_group: group }
};
return msg;
